public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null) return res;
    backtrack(nums, 0, res);
    return res;
}

private void backtrack(int[] nums, int start, List<List<Integer>> res) {
    if (start == nums.length) {
        List<Integer> perm = new ArrayList<>();
        for (int num : nums) perm.add(num);
        res.add(perm);
        return;
    }
    for (int i = start; i < nums.length; i++) {
        swap(nums, start, i);
        backtrack(nums, start + 1, res);
        swap(nums, start, i);
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) return 0;
    Set<String> common = null;
    for (String s : strings) {
        Set<String> subs = new HashSet<>();
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                String sub = s.substring(i, j);
                subs.add(sub);
                subs.add(new StringBuilder(sub).reverse().toString());
            }
        }
        if (common == null) {
            common = subs;
        } else {
            common.retainAll(subs);
        }
        if (common.isEmpty()) return 0;
    }
    int maxLen = 0;
    for (String sub : common) {
        if (sub.length() > maxLen) maxLen = sub.length();
    }
    return maxLen;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) return 0;
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] cur = stack.pop();
                    int cr = cur[0], cc = cur[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dr[k];
                        int nc = cc + dc[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                            !visited[nr][nc] && grid[nr][nc] == '@') {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return count;
}

