public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k <= 0) {
        return false; // divisor must be positive
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        count[r]++;
    }
    // Check remainder 0
    if (count[0] % 2 != 0) {
        return false;
    }
    // Check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // when k is even and r == k/2
            if (count[r] % 2 != 0) {
                return false;
            }
        } else {
            if (count[r] != count[k - r]) {
                return false;
            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] time = {0};
    dfs(0, -1, graph, hasApple, time);
    return time[0];
}

private boolean dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple, int[] time) {
    boolean hasAppleInSubtree = hasApple[node];
    for (int neighbor : graph[node]) {
        if (neighbor == parent) continue;
        boolean childHasApple = dfs(neighbor, node, graph, hasApple, time);
        if (childHasApple) {
            time[0] += 2; // go to child and back
            hasAppleInSubtree = true;
        }
    }
    return hasAppleInSubtree;
}

public String sortString(String s) {
    if (s == null) return null;
    if (s.isEmpty()) return "";
    java.util.TreeMap<Character, Integer> map = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        map.put(c, map.getOrDefault(c, 0) + 1);
    }
    StringBuilder sb = new StringBuilder();
    while (!map.isEmpty()) {
        // Ascending pass
        Character cur = map.firstKey();
        sb.append(cur);
        int cnt = map.get(cur);
        if (cnt == 1) map.remove(cur);
        else map.put(cur, cnt - 1);
        while (true) {
            Character next = map.higherKey(cur);
            if (next == null) break;
            sb.append(next);
            cnt = map.get(next);
            if (cnt == 1) map.remove(next);
            else map.put(next, cnt - 1);
            cur = next;
        }
        if (map.isEmpty()) break;
        // Descending pass
        cur = map.lastKey();
        sb.append(cur);
        cnt = map.get(cur);
        if (cnt == 1) map.remove(cur);
        else map.put(cur, cnt - 1);
        while (true) {
            Character next = map.lowerKey(cur);
            if (next == null) break;
            sb.append(next);
            cnt = map.get(next);
            if (cnt == 1) map.remove(next);
            else map.put(next, cnt - 1);
            cur = next;
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    int maxK = n / 2;
    boolean[][] dp = new boolean[maxK + 1][totalSum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        for (int k = maxK; k >= 1; k--) {
            for (int sum = totalSum - num; sum >= 0; sum--) {
                if (dp[k - 1][sum]) {
                    dp[k][sum + num] = true;
                }
            }
        }
    }
    for (int k = 1; k <= maxK; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k][target]) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    int curr = 0;

    for (int i = 2; i <= n; i++) {
        curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return curr;
}

