public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) return 0;
    int curMax = nums[0];
    int maxSum = nums[0];
    int curMin = nums[0];
    int minSum = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        curMax = Math.max(val, curMax + val);
        maxSum = Math.max(maxSum, curMax);
        curMin = Math.min(val, curMin + val);
        minSum = Math.min(minSum, curMin);
    }
    long maxAbs = Math.max((long)maxSum, -(long)minSum);
    return (int)maxAbs;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) return 0;
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int sz = fibs.size();
        int next = fibs.get(sz - 1) + fibs.get(sz - 2);
        if (next > k) break;
        fibs.add(next);
    }
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        int f = fibs.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
        if (remaining == 0) break;
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> small = new java.util.ArrayList<>();
    java.util.List<Integer> large = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    // large is in descending order, reverse it to ascending
    java.util.Collections.reverse(large);
    int total = small.size() + large.size();
    if (k > total) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        return large.get(k - small.size() - 1);
    }
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            if (Math.abs(top - c) == 32) { // opposite case same letter
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int max = 0;
    int totalMasks = 1 << (n - 1); // number of ways to cut between characters
    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.HashSet<String> seen = new java.util.HashSet<>();
        int start = 0;
        boolean ok = true;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) { // cut after position i
                String sub = s.substring(start, i + 1);
                if (!seen.add(sub)) {
                    ok = false;
                    break;
                }
                start = i + 1;
            }
        }
        if (!ok) continue;
        // add the last substring
        String sub = s.substring(start, n);
        if (!seen.add(sub)) continue;
        max = Math.max(max, seen.size());
    }
    return max;
}

