}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    Queue<Long> queue = new LinkedList<>();

    // Start BFS from each single digit (0-9)
    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }

    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }

        int lastDigit = (int) (num % 10);
        // Next possible digits are lastDigit-1 and lastDigit+1
        if (lastDigit > 0) {
            long nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            long nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }

    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    int count = 0;
    for (int factor = 1; factor <= n; factor *= 10) {
        int lower = n % factor;
        int current = (n / factor) % 10;
        int higher = n / (factor * 10);
        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
    }
    return count;
}

